        if line:
            import json
            data = json.loads(line)
            shipments[data["shipment_id"]] = data

with open(Path("/app/task_file/input_data/warehouses.jsonl")) as f:
    for line in f:
        line = line.strip()
        if line:
            data = json.loads(line)
            warehouses[data["warehouse_id"]] = data

with open(Path("/app/task_file/input_data/destinations.jsonl")) as f:
    for line in f:
        line = line.strip()
        if line:
            data = json.loads(line)
            destinations[data["destination_id"]] = data

with open(Path("/app/task_file/input_data/routes.jsonl")) as f:
    for line in f:
        line = line.strip()
        if line:
            data = json.loads(line)
            routes[data["route_id"]] = data

# Build route map
route_by_wh_dest = {}
for route_id, route in routes.items():
    key = (route["warehouse_id"], route["destination_id"])
    route_by_wh_dest[key] = route

# Validate constraints for first 10 assignments
errors = []

for assignment in assignments[:10]:
    shipment_id = assignment["shipment_id"]
    shipment = shipments.get(shipment_id)
    warehouse_id = assignment["warehouse_id"]
    destination_id = assignment["destination_id"]

    # Constraint 4: Warehouse capabilities
    if shipment and (shipment.get("requires_hazmat", False) or shipment.get("requires_refrigerated", False) or shipment.get("requires_oversized", False)):
        wh = warehouses.get(warehouse_id)
        if not wh:
            errors.append(f"Missing warehouse for shipment {shipment_id}")

        # Check capabilities
        if shipment.get("requires_hazmat", False) and not wh.get("handles_hazmat", False):
            errors.append(f"Constraint 4: Warehouse {warehouse_id} cannot handle hazmat")

        if shipment.get("requires_refrigerated", False) and not wh.get("handles_refrigerated", False):
            errors.append(f"Constraint 4: Warehouse {warehouse_id} cannot handle refrigerated")

        if shipment.get("requires_oversized", False) and not wh.get("handles_oversized", False):
            errors.append(f"Constraint 4: Warehouse {warehouse_id} cannot handle oversized")

    # Constraint 5: Route validity
    route_key = (warehouse_id, destination_id)
    if route_key not in route_by_wh_dest:
        errors.append(f"Constraint 5: No route for (warehouse={warehouse_id}, destination={destination_id})")

print(f"Validation errors for first 10 assignments: {len(errors)}")
for error in errors[:5]:
    print(f"- {error}")
